from collections import deque
def solve2(gin):
    H=len(gin); W=len(gin[0])
    def nb(r,c):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr==dc==0: continue
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W: yield nr,nc
    outside=set(); dq=deque()
    for c in range(W):
        for r in (0,H-1):
            if gin[r][c]==0 and (r,c) not in outside: outside.add((r,c)); dq.append((r,c))
    for r in range(H):
        for c in (0,W-1):
            if gin[r][c]==0 and (r,c) not in outside: outside.add((r,c)); dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for nr,nc in nb(r,c):
            if gin[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); dq.append((nr,nc))
    enc={(r,c) for r in range(H) for c in range(W) if gin[r][c]==0 and (r,c) not in outside}
    out2=[row[:] for row in gin]
    ones={(r,c) for r in range(H) for c in range(W) if gin[r][c]==1}
    # closed shape cells = ones adjacent to enc
    closed1={(nr,nc) for (r,c) in enc for nr,nc in nb(r,c) if gin[nr][nc]==1}
    for (r,c) in enc:
        if any((nr,nc) in ones for nr,nc in nb(r,c)): out2[r][c]=3
    for (r,c) in outside:
        if any((nr,nc) in closed1 for nr,nc in nb(r,c)): out2[r][c]=2
    return out2, enc, closed1, outside

