def variants(gin):
    H=len(gin); W=len(gin[0])
    def nb(r,c):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr==dc==0: continue
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W: yield nr,nc
    outside=set(); dq=deque()
    for c in range(W):
        for r in (0,H-1):
            if gin[r][c]==0: outside.add((r,c)); dq.append((r,c))
    for r in range(H):
        for c in (0,W-1):
            if gin[r][c]==0: outside.add((r,c)); dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for nr,nc in nb(r,c):
            if gin[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); dq.append((nr,nc))
    enc={(r,c) for r in range(H) for c in range(W) if gin[r][c]==0 and (r,c) not in outside}
    ones={(r,c) for r in range(H) for c in range(W) if gin[r][c]==1}
    closed1={(nr,nc) for (r,c) in enc for nr,nc in nb(r,c) if gin[nr][nc]==1}
    # shape components
    comps=[]; seen=set()
    for cell in ones:
        if cell in seen: continue
        comp=set(); dq2=deque([cell]); seen.add(cell)
        while dq2:
            r,c=dq2.popleft(); comp.add((r,c))
            for nr,nc in nb(r,c):
                if gin[nr][nc]==1 and (nr,nc) not in seen:
                    seen.add((nr,nc)); dq2.append((nr,nc))
        comps.append(comp)
    def ring_bbox(comp):
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        return {(r,c) for r in range(min(rs)-1,max(rs)+2) for c in range(min(cs)-1,max(cs)+2)
                if 0<=r<H and 0<=c<W and gin[r][c]==0 and (r,c) not in enc}
    res={}
    # V1 adjacency
    o=[row[:] for row in gin]
    for (r,c) in enc:
        if any((nr,nc) in ones for nr,nc in nb(r,c)): o[r][c]=3
    for (r,c) in outside:
        if any((nr,nc) in closed1 for nr,nc in nb(r,c)): o[r][c]=2
    res['V1']=o
    # V8 bbox ring for closed comps (comp has enc region)
    o8=[row[:] for row in gin]
    for (r,c) in enc:
        if any((nr,nc) in ones for nr,nc in nb(r,c)): o8[r][c]=3
    closed_comps=[cp for cp in comps if any(gin[r][c]==0 and (r,c) in enc for r,c in (nb(x[0],x[1]) for x in []))] if False else [cp for cp in comps if any((nr,nc) in enc for cell in cp for nr,nc in nb(*cell))]
    for cp in closed_comps:
        for (r,c) in ring_bbox(cp): o8[r][c]=2
    res['V8']=o8
    return res, enc, comps

