def parse(txt, name):
    m = re.search(name + r' input \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)\n?' + name + r' output \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)', txt)
    h,w = int(m.group(1)), int(m.group(2))
    gi = [[int(x) for x in r.split()] for r in m.group(3).strip().split('\n')]
    go = [[int(x) for x in r.split()] for r in m.group(6).strip().split('\n')]
    assert len(gi)==h and len(gi[0])==w and len(go)==h, (name, len(gi), len(go))
    return gi, go

