        return [(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc) and 0<=r+dr<Hh and 0<=c+dc<Ww]
    # outside flood (8-conn over zeros)
    outside=set(); dq=deque()
