        for r in (0,Hh-1):
            if gin[r][c]==0 and (r,c) not in outside: outside.add((r,c)); dq.append((r,c))
    for r in range(Hh):
        for c in (0,Ww-1):
            if gin[r][c]==0 and (r,c) not in outside: outside.add((r,c)); dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for nr,nc in nb8(r,c):
            if gin[nr][nc]==0 and (nr,nc) not in outside: outside.add((nr,nc)); dq.append((nr,nc))
    enc={(r,c) for r in range(Hh) for c in range(Ww) if gin[r][c]==0 and (r,c) not in outside}
    # closed shapes = components of 1s that have enclosed cells 8-adjacent to them... use: components with any enc cell adjacent
    seen=set(); comps=[]
    for r in range(Hh):
        for c in range(Ww):
            if gin[r][c]==1 and (r,c) not in seen:
                comp=set([(r,c)]); dq=deque([(r,c)]); seen.add((r,c))
                while dq:
                    a,b=dq.popleft()
                    for nr,nc in nb8(a,b):
                        if gin[nr][nc]==1 and (nr,nc) not in seen: seen.add((nr,nc)); comp.add((nr,nc)); dq.append((nr,nc))
                comps.append(comp)
    res=[[0]*Ww for _ in range(Hh)]
    closed_comps=[cp for cp in comps if any((nr,nc) in enc for cell_ in cp for nr,nc in nb8(*cell_))]
    for cp in closed_comps:
        rs=[a for a,b in cp]; cs=[b for a,b in cp]
        bb={(r,c) for r in range(min(rs)-1,max(rs)+2) for c in range(min(cs)-1,max(cs)+2)
            if 0<=r<Hh and 0<=c<Ww}
        for (r,c) in bb:
            if gin[r][c]==0 and (r,c) not in enc:
                res[r][c]=2
        # hole layers: 3 if 8-adj to shape else 0
        for (r,c) in enc:
            if any((nr,nc) in cp for nr,nc in nb8(r,c)):
                res[r][c]=3
    for (r,c) in enc:
        if res[r][c]==0: pass
    # mark remaining enc cells 0, keep 1s
    for r in range(Hh):
        for c in range(Ww):
            if gin[r][c]==1: res[r][c]=1
    return res, enc, closed_comps

