    def nb(r,c):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr==0 and dc==0: continue
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W: yield nr,nc
    outside=set()
    dq=deque((r,c) for r in range(H) for c in range(W) if grid[r][c]==0 and (r in(0,H-1) or c in(0,W-1)))
    outside|=set(dq)
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and grid[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); dq.append((nr,nc))
    enc={(r,c) for r in range(H) for c in range(W) if grid[r][c]==0 and (r,c) not in outside}
    closed1={(r,c) for r in range(H) for c in range(W) if grid[r][c]==1 and any((nr,nc) in enc for nr,nc in nb(r,c))}
    res=[row[:] for row in grid]
