                            seen.add((nr,nc)); comp.add((nr,nc)); q2.append((nr,nc))
                if any(cell_ in closed1 for cell_ in comp): comps.append(comp)
    def isring(rr,cc):
        return 0<=rr<Hh and 0<=cc<Ww and res[rr][cc]==2 and any((nr,nc) in closed1 for nr,nc in nb8(rr,cc))
    for comp in comps:
        rs=[a for a,b in comp]; cs=[b for a,b in comp]
        for corner,(dr_,dc_) in [((min(rs)-1,min(cs)-1),(1,1)),((min(rs)-1,max(cs)+1),(1,-1)),
                                 ((max(rs)+1,min(cs)-1),(-1,1)),((max(rs)+1,max(cs)+1),(-1,-1))]:
