def enc4_vs_8(gi_):
    H2,W2=len(gi_),len(gi_[0])
    def nb8f(r,c):
        return [(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc) and 0<=r+dr<H2 and 0<=c+dc<W2]
    def flood(conn8):
        outs=set(); dq3=deque((r,c) for r in range(H2) for c in range(W2) if gi_[r][c]==0 and (r in(0,H2-1) or c in(0,W2-1)))
        outs|=set(dq3)
        while dq3:
            r,c=dq3.popleft()
            nbs = nb8f(r,c) if conn8 else [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]
            for nr,nc in nbs:
                if 0<=nr<H2 and 0<=nc<W2 and gi_[nr][nc]==0 and (nr,nc) not in outs:
                    outs.add((nr,nc)); dq3.append((nr,nc))
        return {(r,c) for r in range(H2) for c in range(W2) if gi_[r][c]==0 and (r,c) not in outs}
    return flood(False), flood(True)
