def solve_pstar(gi_):
    H2,W2=len(gi_),len(gi_[0])
    def nb8f(r,c):
        return [(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc) and 0<=r+dr<H2 and 0<=c+dc<W2]
    def orth(r,c):
        return [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]
    e4,_=enc4_vs_8(gi_)
    cl1={(r,c) for r in range(H2) for c in range(W2) if gi_[r][c]==1 and any((nr,nc) in e4 for nr,nc in nb8f(r,c))}
    out=[row[:] for row in gi_]
    for r in range(H2):
        for c in range(W2):
            if gi_[r][c]!=0: continue
            if (r,c) in e4:
                out[r][c]= 3 if any((nr,nc) in cl1 for nr,nc in nb8f(r,c)) else 0
            elif any((nr,nc) in cl1 for nr,nc in nb8f(r,c)):
                out[r][c]=2
            else:
                # P* check
                fill=False
                for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                    R=(r+dr,c+dc)
                    if R not in cl1 and R in {(rr,cc) for rr in range(H2) for cc in range(W2)} and gi_[R[0]][R[1]]==0 and (R[0],R[1]) not in e4 and any((nr,nc) in cl1 for nr,nc in nb8f(*R)):
                        o1=sum(1 for nr,nc in orth(*R) if (nr,nc) in cl1)
                        d1s=sum(1 for dr2,dc2 in ((1,1),(1,-1),(-1,1),(-1,-1)) if (R[0]+dr2,R[1]+dc2) in cl1)
                        if o1>=2 and d1s==1:
                            fill=True
                out[r][c]=2 if fill else 0
    return out
