def outside_flood(gi):
    R,C=dims(gi); outside=set(); q=deque()
    for r in range(R):
        for c in (0,C-1):
            if gi[r][c]==0: outside.add((r,c)); q.append((r,c))
    for c in range(C):
        for r in (0,R-1):
            if gi[r][c]==0: outside.add((r,c)); q.append((r,c))
    while q:
        a_,b_=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a_+dr,b_+dc
            if 0<=x<R and 0<=y<C and gi[x][y]==0 and (x,y) not in outside:
                outside.add((x,y)); q.append((x,y))
    return outside

