def sig5(gi_,r,c,R,C):
    s=[]
    for dr in range(-2,3):
        for dc in range(-2,3):
            if dr==0 and dc==0: continue
            x,y=r+dr,c+dc
            s.append(gi_[x][y] if 0<=x<R and 0<=y<C else -1)
    return tuple(s)

